// py-errors.mjs
//
// Python-shaped error objects and the fatal-error reporting path.
//
// The reference implementation is a PyInstaller bundle of a CPython script. When
// the script raises, CPython writes a traceback to stderr and the interpreter
// exits with status 1. This module reproduces the observable contract:
//
//   * stderr ends with exactly `<ExceptionName>: <message>\n`
//   * the process exit status is 1
//   * stdout stays empty
//
// The intermediate `File "...", line N, in f` frame lines are cosmetic (the real
// binary emits frozen-module paths that cannot be reproduced), but we emit a
// faithfully shaped set so the output reads like a real traceback.

import process from 'node:process';

/** Successful termination. */
export const EXIT_OK = 0;
/** An uncaught Python exception reached the top level. */
export const EXIT_RUNTIME_ERROR = 1;
/** argparse rejected the command line. */
export const EXIT_ARG_ERROR = 2;

/**
 * The analogue of Python's built-in `ValueError`.
 *
 * `name` is overridden so that traceback rendering and any `instanceof`-free
 * duck typing both see the Python spelling rather than `Error`/`PyValueError`.
 */
export class PyValueError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ValueError';
  }
}

/**
 * Render one traceback frame line.
 *
 * A frame may be given either as a pre-formatted string (used verbatim, so
 * callers can paste literal traceback lines) or as `{ file, line, name }`, where
 * `file` defaults to the enclosing script's filename.
 */
function formatFrame(frame, pyFile) {
  if (typeof frame === 'string') return frame;
  const file = frame.file === undefined ? pyFile : frame.file;
  return `  File "${file}", line ${frame.line}, in ${frame.name}`;
}

/**
 * Write a CPython-style traceback for `err` to stderr.
 *
 * Deliberately does NOT exit: the caller sets `process.exitCode` so that a piped
 * stdout/stderr is flushed before the process tears down.
 *
 * @param {Error} err     the exception to report
 * @param {string} pyFile filename used for frames that omit one (e.g. 'test7.py')
 * @param {Array<string|{file?: string, line: number|string, name: string}>} frames
 *        innermost-last, matching Python's "most recent call last" ordering
 */
export function pythonFatal(err, pyFile = 'test7.py', frames = []) {
  const lines = ['Traceback (most recent call last):'];
  for (const frame of frames) lines.push(formatFrame(frame, pyFile));

  // Python prints `Name: message`, or a bare `Name` when the message is empty.
  const name = err && err.name ? err.name : 'Exception';
  const message = err && err.message ? String(err.message) : '';
  lines.push(message === '' ? name : `${name}: ${message}`);

  process.stderr.write(lines.join('\n') + '\n');
}

// python-bytes.mjs
//
// The two Python primitives the CLI leans on:
//
//   * `str.encode()`  -> strict UTF-8 bytes. Every length check in the program
//                        ("must be 16 bytes") is against this byte length, never
//                        against a JS string's UTF-16 `.length`.
//   * `repr(bytes)`   -> the `b'...'` literal that `print()` emits.
//
// Both are implemented by hand so the module has no dependencies at all.

import process from 'node:process';

/**
 * Exactly Python's `str.encode()` (i.e. `encode('utf-8')`).
 *
 * Iteration is over UTF-16 code units so that surrogate pairs can be combined
 * explicitly and lone surrogates handled deliberately. (`for...of` would hand us
 * lone surrogates as-is and tempt an encoder into emitting CESU-8.)
 *
 * A lone surrogate is encoded as U+FFFD, matching WHATWG `TextEncoder` and
 * `Buffer.from(s, 'utf8')`. CPython would instead raise UnicodeEncodeError, but
 * that case is unreachable from a Node port: `process.argv` has already replaced
 * undecodable argv bytes with U+FFFD before user code runs.
 *
 * @param {string} str
 * @returns {Uint8Array}
 */
export function encodeUtf8(str) {
  const out = [];
  for (let i = 0; i < str.length; i++) {
    let cp = str.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      // High surrogate: consume the low surrogate if there is one.
      const lo = i + 1 < str.length ? str.charCodeAt(i + 1) : 0;
      if (lo >= 0xdc00 && lo <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
        i++;
      } else {
        cp = 0xfffd;
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = 0xfffd; // unpaired low surrogate
    }

    if (cp < 0x80) {
      out.push(cp);
    } else if (cp < 0x800) {
      out.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      out.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      out.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f),
      );
    }
  }
  return Uint8Array.from(out);
}

/**
 * Length of `str.encode()` in bytes — i.e. what Python's length checks compare.
 *
 * @param {string} str
 * @returns {number}
 */
export function utf8ByteLength(str) {
  return encodeUtf8(str).length;
}

const HEX = '0123456789abcdef';
const SQ = 0x27; // '
const DQ = 0x22; // "
const BACKSLASH = 0x5c;

/**
 * Exactly Python's `repr(bytes)` (CPython's `bytes_repr`). No trailing newline.
 *
 * @param {Uint8Array|number[]} bytes
 * @returns {string} pure ASCII, so any of ascii/latin1/utf8 write encodings match
 */
export function bytesRepr(bytes) {
  // Quote selection scans the whole buffer first: a single quote is used unless
  // the payload contains ' and no ", in which case " becomes the delimiter so
  // the ' can be written literally.
  let hasSingle = false;
  let hasDouble = false;
  for (let i = 0; i < bytes.length; i++) {
    const b = bytes[i];
    if (b === SQ) hasSingle = true;
    else if (b === DQ) hasDouble = true;
  }
  const quote = hasSingle && !hasDouble ? DQ : SQ;
  const quoteChar = String.fromCharCode(quote);

  let out = 'b' + quoteChar;
  for (let i = 0; i < bytes.length; i++) {
    const b = bytes[i];
    if (b === quote || b === BACKSLASH) {
      // Must precede the printable-range test: ', " and \ are all printable.
      // Note the *other* quote is never escaped, so `\"` is never produced.
      out += '\\' + String.fromCharCode(b);
    } else if (b === 0x09) {
      out += '\\t';
    } else if (b === 0x0a) {
      out += '\\n';
    } else if (b === 0x0d) {
      out += '\\r';
    } else if (b < 0x20 || b >= 0x7f) {
      // Lowercase, always two digits. There are no \a \b \f \v \0 escapes, and
      // 0x7f (DEL) is escaped too — hence `>= 0x7f`, not `> 0x7f`.
      out += '\\x' + HEX[b >> 4] + HEX[b & 0x0f];
    } else {
      out += String.fromCharCode(b);
    }
  }
  return out + quoteChar;
}

/**
 * Python's `print(some_bytes)`: the repr followed by exactly one '\n'.
 *
 * @param {Uint8Array|number[]} bytes
 */
export function pyPrintBytes(bytes) {
  process.stdout.write(bytesRepr(bytes) + '\n');
}

// Scratch self-test for the `pybytes` track. NOT a deliverable (lives outside /output).
//
//   node /workspace/verify/t-bytes.mjs
//
// Checks bytesRepr / encodeUtf8 against every documented oracle sample, a bulk
// corpus of real oracle output (/workspace/verify/oracle-lines.txt), full
// 0x00-0xFF coverage, and the quote-selection matrix.

import { readFileSync } from 'node:fs';
import process from 'node:process';
import { bytesRepr, encodeUtf8, utf8ByteLength } from '../../output/lib/python-bytes.mjs';
import { PyValueError, EXIT_OK, EXIT_RUNTIME_ERROR, EXIT_ARG_ERROR } from '../../output/lib/py-errors.mjs';

let pass = 0;
const failures = [];

function check(name, cond, detail) {
  if (cond) pass++;
  else failures.push(`${name}${detail ? ' :: ' + detail : ''}`);
}

function eq(name, got, want) {
  check(name, got === want, `got ${JSON.stringify(got)} want ${JSON.stringify(want)}`);
}

// ---------------------------------------------------------------------------
// Independent strict decoder for a Python bytes literal.
// Deliberately written as a parser (not a mirror of bytesRepr) and throws on any
// escape outside the documented set, so an unexpected escape can never slip by.
// ---------------------------------------------------------------------------
const SIMPLE = { t: 0x09, n: 0x0a, r: 0x0d, '\\': 0x5c, "'": 0x27, '"': 0x22 };

function decodeBytesLiteral(lit) {
  if (lit[0] !== 'b') throw new Error(`no b prefix: ${lit}`);
  const q = lit[1];
  if (q !== "'" && q !== '"') throw new Error(`bad quote: ${lit}`);
  if (lit[lit.length - 1] !== q) throw new Error(`unterminated: ${lit}`);
  const body = lit.slice(2, -1);
  const out = [];
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (c !== '\\') {
      const code = body.charCodeAt(i);
      if (code < 0x20 || code > 0x7e) throw new Error(`raw non-printable 0x${code.toString(16)}`);
      if (c === q) throw new Error(`unescaped delimiter inside body: ${lit}`);
      out.push(code);
      continue;
    }
    const e = body[++i];
    if (e === 'x') {
      const hex = body.slice(i + 1, i + 3);
      if (!/^[0-9a-fA-F]{2}$/.test(hex)) throw new Error(`bad \\x escape: ${hex}`);
      out.push(parseInt(hex, 16));
      i += 2;
    } else if (Object.prototype.hasOwnProperty.call(SIMPLE, e)) {
      out.push(SIMPLE[e]);
    } else {
      throw new Error(`unknown escape \\${e} in ${lit}`);
    }
  }
  return Uint8Array.from(out);
}

// ---------------------------------------------------------------------------
// A. The documented oracle samples, verbatim.
// ---------------------------------------------------------------------------
const SAMPLES = [
  // Mission-context happy path (key '6G!I:]M.SYzm[v9[' / iv '*ANz^hUTfAHTf!he').
  "b'3\\xe9\\xbb\\x12r\\xe6Rd\\xdf\\xbb\\xed@\\xf1\\x1bZ\\x14'",
  "b'-\\xdf\\x14]\\xf5\\xd9\\xc4\\x1e\\xefiq\\xdeI\\xe3\\x08H'",
  // Mission-context repr samples.
  "b'\\xc2z\\x9f&\\x82LS\\xce\\x98\\x91\\x80Ei\\xb0\\xe6+'",
  'b"\\x97n/\'\\xd5\\x94\\x9c\\xfd\\xee\\x15\\xa7=\\x8d\\xbcYS"',
  "b'0g\\xe9k\\xb7\\x91\\t\\x9b\\x95E\\x02U\\xcc\\xe3\\'\"'",
  // Spec table rows, re-probed from the oracle in this session.
  "b'\\x00\\x1c\\x08\\x01W\\xebD#_\\x04+\\xb5\"\\n\\xbb\\xe3'",   // i=2  line1
  "b'\\xe7\\xd6\\x9e>\\x98\\xbc5\\xdcB]9\\xdd\\x89\\xa9\\t\\xcb'", // i=5  line1
  "b'\\xd2\\x11\\x15\\xf2%e\\x1fH\\xbe\\xeb\\x80\\xf7\\xb4b\\x0c\\r'", // i=6 line2
  'b"D\'\\xbb\\x8a\\xa7\\x911#\\xb3\\x99_:\\xb7\\xd3S\\x92"',      // i=18 line1
  "b'K\\xe3i\\x84\\xbf\\xf8\">^\\xca\\'*\\xed\\x1e\\xb2b'",        // i=52 line1
  "b'\\xf2\\xcb\\x95\\xf7\\xab\\x13^\\xa3@Q\\xdbDW \\\\q'",        // i=52 line2
  'b"\\\\\\\\\\xc0\\xe3\\xdd\\x13\\xcc\\x80Y*zt\\xa6\'s\\xc7"',    // i=1740 line2
  "b'\\x02/\\x0f\\xb0\\xe9\\x9f\\x97\\x9c\\xfa\\\\t\\xc2\\xa3\\xc4\\xdap'", // i=490 line1
  "b'0\\x95\\xd6N\\x8e\"o\\xa45\\xf9\\x7f\\x19\\'\\x0bS\\xe4'",    // i=96 line1
];

for (const lit of SAMPLES) {
  const bytes = decodeBytesLiteral(lit);
  eq(`sample roundtrip ${lit}`, bytesRepr(bytes), lit);
  check(`sample is 16 bytes ${lit}`, bytes.length === 16, `len=${bytes.length}`);
}

// ---------------------------------------------------------------------------
// B. Bulk corpus of real oracle lines.
// ---------------------------------------------------------------------------
const corpus = readFileSync('/workspace/verify/oracle-lines.txt', 'latin1')
  .split('\n')
  .filter((l) => l.length > 0);
check('corpus is non-trivial', corpus.length >= 1000, `lines=${corpus.length}`);

const seen = new Set();
let outerSingle = 0;
let outerDouble = 0;
let mismatch = 0;
let badLen = 0;
let escapedSqInSq = 0;
let bareSqInDq = 0;
let bareDqInSq = 0;

for (const line of corpus) {
  const bytes = decodeBytesLiteral(line); // throws on any unknown escape
  if (bytesRepr(bytes) !== line) mismatch++;
  if (bytes.length !== 16) badLen++;
  for (const b of bytes) seen.add(b);
  if (line[1] === "'") outerSingle++;
  else outerDouble++;
  // Quote rule, recomputed here from the decoded bytes, independently of bytesRepr.
  const hasSq = bytes.includes(0x27);
  const hasDq = bytes.includes(0x22);
  const wantQuote = hasSq && !hasDq ? '"' : "'";
  if (line[1] !== wantQuote) mismatch++;
  if (line.includes("\\'")) escapedSqInSq += line[1] === "'" ? 1 : -1000;
  if (line[1] === '"' && line.slice(2, -1).includes("'")) bareSqInDq++;
  if (line[1] === "'" && line.slice(2, -1).includes('"')) bareDqInSq++;
  check('no escaped double quote', !line.includes('\\"'), line);
  check('no uppercase hex escape', !/\\x[0-9a-f]*[A-F]/.test(line), line);
}

eq('corpus reprs all match', mismatch, 0);
eq('corpus blocks all 16 bytes', badLen, 0);
eq('corpus byte coverage 256/256', seen.size, 256);
check('corpus saw both quote styles', outerSingle > 0 && outerDouble > 0, `${outerSingle}/${outerDouble}`);
check("corpus saw escaped ' inside '...'", escapedSqInSq > 0, String(escapedSqInSq));
check("corpus saw bare ' inside \"...\"", bareSqInDq > 0, String(bareSqInDq));
check('corpus saw bare " inside \'...\'', bareDqInSq > 0, String(bareDqInSq));

// ---------------------------------------------------------------------------
// C. Every byte value, in isolation, against a hand-written expectation table.
// ---------------------------------------------------------------------------
// 0x20..0x7e written out literally, so the expectation does not reuse any of the
// production code's range arithmetic.
const PRINTABLE =
  ' !"#$%&\'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~';
const LOWER_HEX = '0123456789abcdef'.split('');

for (let b = 0; b < 256; b++) {
  let inner;
  if (b === 0x27) inner = '\\\''; //  a lone ' -> outer quote becomes "
  else if (b === 0x22) inner = '"';
  else if (b === 0x5c) inner = '\\\\';
  else if (b === 0x09) inner = '\\t';
  else if (b === 0x0a) inner = '\\n';
  else if (b === 0x0d) inner = '\\r';
  else if (b >= 0x20 && b <= 0x7e) inner = PRINTABLE[b - 0x20];
  else inner = '\\x' + LOWER_HEX[Math.floor(b / 16)] + LOWER_HEX[b % 16];

  // The only single-byte buffer that flips the delimiter is 0x27.
  const want = b === 0x27 ? 'b"\'"' : `b'${inner}'`;
  eq(`single byte 0x${b.toString(16).padStart(2, '0')}`, bytesRepr(Uint8Array.of(b)), want);
}

// Spot checks for escapes Python deliberately does NOT have.
eq('0x07 has no \\a', bytesRepr(Uint8Array.of(0x07)), "b'\\x07'");
eq('0x08 has no \\b', bytesRepr(Uint8Array.of(0x08)), "b'\\x08'");
eq('0x0b has no \\v', bytesRepr(Uint8Array.of(0x0b)), "b'\\x0b'");
eq('0x0c has no \\f', bytesRepr(Uint8Array.of(0x0c)), "b'\\x0c'");
eq('0x00 has no \\0', bytesRepr(Uint8Array.of(0x00)), "b'\\x00'");
eq('0x7f (DEL) escaped', bytesRepr(Uint8Array.of(0x7f)), "b'\\x7f'");
eq('0x7e not escaped', bytesRepr(Uint8Array.of(0x7e)), "b'~'");
eq('0xff escaped lowercase', bytesRepr(Uint8Array.of(0xff)), "b'\\xff'");

// ---------------------------------------------------------------------------
// D. Quote-selection matrix + misc shapes.
// ---------------------------------------------------------------------------
eq('neither quote', bytesRepr(encodeUtf8('ab')), "b'ab'");
eq("only '", bytesRepr(Uint8Array.of(0x61, 0x27, 0x62)), 'b"a\'b"');
eq('only "', bytesRepr(Uint8Array.of(0x61, 0x22, 0x62)), "b'a\"b'");
eq('both quotes', bytesRepr(Uint8Array.of(0x27, 0x22)), "b'\\'\"'");
eq('both quotes reversed', bytesRepr(Uint8Array.of(0x22, 0x27)), "b'\"\\''");
eq('backslash inside "..."', bytesRepr(Uint8Array.of(0x5c, 0x27)), 'b"\\\\\'"');
eq('empty bytes', bytesRepr(new Uint8Array(0)), "b''");
eq('plain number array accepted', bytesRepr([0x61, 0x09, 0xff]), "b'a\\t\\xff'");
eq('0x5c followed by t distinct from tab', bytesRepr(Uint8Array.of(0x5c, 0x74)), "b'\\\\t'");

// ---------------------------------------------------------------------------
// E. encodeUtf8 == Python str.encode(), cross-checked against Buffer/TextEncoder.
// ---------------------------------------------------------------------------
const te = new TextEncoder();
const STRINGS = [
  '',
  'ccccccccccccccc',
  '6G!I:]M.SYzm[v9[',
  'ccccccccccccccé',        // 15 chars / 16 bytes  -> oracle accepts
  'ccccccccccccc€',     // 14 chars / 16 bytes  -> oracle accepts
  'cccccccccccc\u{1F600}',   // 14 units / 16 bytes  -> oracle accepts
  'cccccccccccccccé',       // 16 chars / 17 bytes  -> oracle rejects
  '�߿ࠀ￿',
  '�',                  // genuine replacement char: 3 legitimate bytes
  '😀',            // surrogate pair
  '\uD800',                  // lone high surrogate
  '\uDC00',                  // lone low surrogate
  'a\uD800b',                // lone high surrogate mid-string
  'a\uD83D',                 // trailing high surrogate at end of string
];
for (const s of STRINGS) {
  const mine = encodeUtf8(s);
  const buf = Uint8Array.from(Buffer.from(s, 'utf8'));
  const enc = te.encode(s);
  eq(`encodeUtf8 vs Buffer ${JSON.stringify(s)}`, mine.join(','), buf.join(','));
  eq(`encodeUtf8 vs TextEncoder ${JSON.stringify(s)}`, mine.join(','), enc.join(','));
}

eq('byte length 16 for c*14+e-acute', utf8ByteLength('ccccccccccccccé'), 16);
eq('byte length 16 for c*13+euro', utf8ByteLength('ccccccccccccc€'), 16);
eq('byte length 16 for c*12+emoji', utf8ByteLength('cccccccccccc\u{1F600}'), 16);
eq('byte length 17 for c*15+e-acute', utf8ByteLength('cccccccccccccccé'), 17);
eq('byte length 0 for empty', utf8ByteLength(''), 0);
eq('byte length 16 for 16 ascii', utf8ByteLength('c'.repeat(16)), 16);
eq('U+FFFD is 3 bytes (not special-cased)', utf8ByteLength('�'), 3);

// ---------------------------------------------------------------------------
// F. py-errors surface.
// ---------------------------------------------------------------------------
const err = new PyValueError('Invalid key size');
eq('PyValueError.name', err.name, 'ValueError');
eq('PyValueError.message', err.message, 'Invalid key size');
check('PyValueError instanceof Error', err instanceof Error);
check('PyValueError instanceof PyValueError', err instanceof PyValueError);
eq('EXIT_OK', EXIT_OK, 0);
eq('EXIT_RUNTIME_ERROR', EXIT_RUNTIME_ERROR, 1);
eq('EXIT_ARG_ERROR', EXIT_ARG_ERROR, 2);

// ---------------------------------------------------------------------------
process.stdout.write(`\npassed: ${pass}   failed: ${failures.length}\n`);
if (failures.length) {
  for (const f of failures.slice(0, 40)) process.stdout.write('FAIL ' + f + '\n');
  process.exitCode = 1;
}

