// Scratch subprocess fixture for the pybytes track (outside /output).
//   node t-fatal.mjs print   -> exercises pyPrintBytes on stdout
//   node t-fatal.mjs fatal   -> exercises pythonFatal on stderr
//   node t-fatal.mjs empty   -> exception with an empty message
import process from 'node:process';
import { pyPrintBytes } from '../../output/lib/python-bytes.mjs';
import { PyValueError, pythonFatal, EXIT_RUNTIME_ERROR } from '../../output/lib/py-errors.mjs';

const mode = process.argv[2];

if (mode === 'print') {
  pyPrintBytes(Uint8Array.of(0x33, 0xe9, 0xbb, 0x12, 0x72, 0xe6, 0x52, 0x64, 0xdf, 0xbb, 0xed, 0x40, 0xf1, 0x1b, 0x5a, 0x14));
  pyPrintBytes(Uint8Array.of(0x2d, 0xdf, 0x14, 0x5d, 0xf5, 0xd9, 0xc4, 0x1e, 0xef, 0x69, 0x71, 0xde, 0x49, 0xe3, 0x08, 0x48));
} else if (mode === 'fatal') {
  // Frame list mirroring the oracle's key-size traceback.
  pythonFatal(new PyValueError('Invalid key size'), 'test7.py', [
    { line: 21, name: '<module>' },
    { line: 13, name: 'main' },
    { file: 'pyaes/aes.py', line: 385, name: '__init__' },
    { file: 'pyaes/aes.py', line: 304, name: '__init__' },
    { file: 'pyaes/aes.py', line: 134, name: '__init__' },
  ]);
  process.exitCode = EXIT_RUNTIME_ERROR;
} else if (mode === 'empty') {
  pythonFatal(new PyValueError(''), 'test7.py', [{ line: 21, name: '<module>' }]);
  process.exitCode = EXIT_RUNTIME_ERROR;
}

